<template>
  <div class="me-resource" v-title :data-title="title">
    <el-container class="">
      <el-main class="me-main">
        <el-card class="me-resource-card">
          <div slot="header" class="me-resource-header">
            <span>卫星地面融合网络社区-技术资源下载</span>
          </div>
          
          <el-tabs v-model="activeTab">
            <el-tab-pane label="技术文档" name="docs">
              <el-table :data="docsList" style="width: 100%">
                <el-table-column prop="name" label="文档名称" width="300"></el-table-column>
                <el-table-column prop="description" label="描述"></el-table-column>
                <el-table-column prop="size" label="大小" width="100"></el-table-column>
                <el-table-column label="操作" width="120">
                  <template slot-scope="scope">
                    <el-button size="small" type="primary" @click="download(scope.row)">下载</el-button>
                  </template>
                </el-table-column>
              </el-table>
            </el-tab-pane>
            
            <el-tab-pane label="代码示例" name="code">
              <el-table :data="codeList" style="width: 100%">
                <el-table-column prop="name" label="代码名称" width="300"></el-table-column>
                <el-table-column prop="description" label="描述"></el-table-column>
                <el-table-column prop="size" label="大小" width="100"></el-table-column>
                <el-table-column label="操作" width="120">
                  <template slot-scope="scope">
                    <el-button size="small" type="primary" @click="download(scope.row)">下载</el-button>
                  </template>
                </el-table-column>
              </el-table>
            </el-tab-pane>
            
            <el-tab-pane label="工具软件" name="tools">
              <el-table :data="toolsList" style="width: 100%">
                <el-table-column prop="name" label="工具名称" width="300"></el-table-column>
                <el-table-column prop="description" label="描述"></el-table-column>
                <el-table-column prop="size" label="大小" width="100"></el-table-column>
                <el-table-column label="操作" width="120">
                  <template slot-scope="scope">
                    <el-button size="small" type="primary" @click="download(scope.row)">下载</el-button>
                  </template>
                </el-table-column>
              </el-table>
            </el-tab-pane>
          </el-tabs>
        </el-card>
      </el-main>
    </el-container>
  </div>
</template>

<script>
  export default {
    name: 'ResourceDownload',
    data() {
      return {
        activeTab: 'docs',
        docsList: [
          {
            name: '卫星通信技术白皮书',
            description: '卫星通信技术的最新发展和应用',
            size: '2.5MB'
          },
          {
            name: '地面网络与卫星网络融合技术指南',
            description: '详细介绍地面网络与卫星网络融合的技术方案',
            size: '3.8MB'
          },
          {
            name: '卫星轨道计算手册',
            description: '卫星轨道计算的基本原理和方法',
            size: '1.2MB'
          }
        ],
        codeList: [
          {
            name: '卫星信号处理代码示例',
            description: '卫星信号处理的Python代码示例',
            size: '500KB'
          },
          {
            name: '网络协议实现代码',
            description: '卫星网络协议的实现代码',
            size: '800KB'
          }
        ],
        toolsList: [
          {
            name: '卫星轨道模拟器',
            description: '模拟卫星轨道运行的工具软件',
            size: '10MB'
          },
          {
            name: '信号分析工具',
            description: '卫星信号分析和处理工具',
            size: '5MB'
          }
        ]
      }
    },
    computed: {
      title (){
        return '资源下载 - 卫星地面融合网络社区'
      }
    },
    methods: {
      download(row) {
        const url = `/download?filename=${encodeURIComponent(row.name)}`
        const a = document.createElement('a')
        a.href = url
        a.download = row.name + '.txt'
        document.body.appendChild(a)
        a.click()
        document.body.removeChild(a)
        
        this.$message({
          type: 'success',
          message: `开始下载: ${row.name}`
        })
      }
    }
  }
</script>

<style scoped>
  .me-resource {
  }

  .el-container {
    width: 960px;
  }

  .me-main {
    overflow: hidden;
  }

  .me-resource-card {
    margin-bottom: 20px;
  }

  .me-resource-header {
    font-size: 18px;
    font-weight: 600;
    color: var(--secondary-color);
  }

  .el-table {
    margin-top: 20px;
  }
</style>


